<?php
session_start();
if(!isset($_SESSION['rol']) || $_SESSION['rol'] !== 'TECNICO'){ header("Location: ../index.php"); exit; }
require_once(__DIR__ . '/../config/db.php');
$pdo=eva_pdo();
$idTec=(int)($_SESSION['id_usuario'] ?? 0);
$fDisp=(int)($_GET['id_dispositivo'] ?? 0);
$where=""; $params=[];
if($fDisp){ $where=" AND s.id_dispositivo=:did"; $params[':did']=$fDisp; }
try{
 $sql="SELECT m.id_medicion, m.distancia_cm, m.nivel_cm, m.porcentaje, m.litros, m.fecha_hora, s.modelo, s.numero_serie, d.nombre AS disp_nombre
 FROM mediciones m JOIN sensores s ON s.id_sensor=m.id_sensor JOIN dispositivos d ON d.id_dispositivo=s.id_dispositivo
 JOIN tecnico_dispositivo td ON td.id_dispositivo=d.id_dispositivo AND td.id_tecnico=:tec
 WHERE 1=1 $where ORDER BY m.fecha_hora DESC LIMIT 50";
 $params[':tec']=$idTec;
 $st=$pdo->prepare($sql); $st->execute($params); $mediciones=$st->fetchAll();
} catch(Throwable $e){ $mediciones=[]; error_log('tec mediciones: '.$e->getMessage()); }
try{ $avgPct=$mediciones ? round(array_sum(array_column($mediciones,'porcentaje'))/count($mediciones),1) : 0; $avgLit=$mediciones ? round(array_sum(array_column(array_filter($mediciones,fn($r)=>$r['litros']!==null),'litros'))/max(1,count(array_filter($mediciones,fn($r)=>$r['litros']!==null))),0) : 0; }catch(Throwable $e){ $avgPct=0; $avgLit=0; }
?>
